window.kbPageData["views/entry/k-a329c346aba5023e"] = {"key":"entry/k-a329c346aba5023e","state":{"route":"entry/k-a329c346aba5023e"},"node":{"id":"k-a329c346aba5023e","mode":"k","title":"银发经济","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#71"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["employment","modern"],"主类":["概念与词义"],"出处性质":["专项题干","机构注释"],"学科":["政治理论","社会治理"],"来源主题":["就业、社保与公共服务"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"银发经济是围绕老年人的产品和服务需求，以及为老龄阶段做准备而开展的经济活动。","review":{"definition":"银发经济是围绕老年人的产品和服务需求，以及为老龄阶段做准备而开展的经济活动。","explanation":"本题①对应《关于深化养老服务改革发展的意见》中的产业发展部署。研发和推广老年用品可以丰富产品供给，拓展养老服务场景可以更好地满足老年人的多样化需求，两者都有助于释放养老消费潜力。因此①正确。","references":[],"evidence":"大力发展银发经济，丰富养老服务场景，释放养老消费潜力","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"a7aa1c1117e2d655","label":"银发经济","topic":"就业、社保与公共服务","category":"非时政","text":"3.银发经济\n银发经济，也称银色经济、银发产业，是向老年人提供产品或服务，以及为老龄阶段做\n准备等一系列经济活动的总和。\n截至 2025 年底，我国 60 岁及以上老年人口达 3.2 亿人，预计到 2035 年，这一群体数\n量将超 4 亿人，银发经济规模有望突破 30 万亿元。","source":{"doc":"6cbfb01fe723bba64b75","first":43,"last":43,"page":43,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#71":{"paper":"政治理论必刷100题","n":71,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",22],"asrc":["国省考政治理论必刷100题.pdf",77],"card":"79ab95a5c60c0e2e5ad0fb9c","links":[{"id":"k-a329c346aba5023e","role":"直接考查","why":"题目考查发展银发经济的具体政策方向，即丰富养老服务场景和释放养老消费潜力。"}]}},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-a329c346aba5023e":[["政治理论必刷100题#71"]]}};
